import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.CNfFRqmr.js";const k=JSON.parse('{"title":"Agent Skills Technical Design","description":"The Skills system follows the Progressive Disclosure principle:","frontmatter":{"title":"Agent Skills Technical Design","description":"The Skills system follows the Progressive Disclosure principle:"},"headers":[],"relativePath":"docs/agent-skills.md","filePath":"docs/agent-skills.md"}'),n={name:"docs/agent-skills.md"};function l(o,s,d,r,h,p){return t(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="agent-skills-technical-design" tabindex="-1">Agent Skills Technical Design <a class="header-anchor" href="#agent-skills-technical-design" aria-label="Permalink to &quot;Agent Skills Technical Design&quot;">​</a></h1><h2 id="_1-design-rationale-progressive-disclosure" tabindex="-1">1. Design Rationale: Progressive Disclosure <a class="header-anchor" href="#_1-design-rationale-progressive-disclosure" aria-label="Permalink to &quot;1. Design Rationale: Progressive Disclosure&quot;">​</a></h2><p>The Skills system follows the <strong>Progressive Disclosure</strong> principle:</p><ul><li><strong>At startup</strong>: only the skills&#39; <code>name</code> + <code>description</code> index is injected into the System Prompt — the full text is not loaded</li><li><strong>At runtime</strong>: the LLM decides whether a given skill is needed based on the user&#39;s task, and loads the full text on demand by calling the <code>use_skill</code> tool</li></ul><p>This avoids the token bloat caused by injecting the full text of every skill into the System Prompt up front, keeping the context window used efficiently.</p><h2 id="_2-directory-structure" tabindex="-1">2. Directory Structure <a class="header-anchor" href="#_2-directory-structure" aria-label="Permalink to &quot;2. Directory Structure&quot;">​</a></h2><p>Each skill is an independent subdirectory; the directory name is the skill identifier, and <code>SKILL.md</code> is the fixed filename:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{workdir}/skills/</span></span>
<span class="line"><span>├── go-coding-standards/</span></span>
<span class="line"><span>│   └── SKILL.md</span></span>
<span class="line"><span>├── debugging-guide/</span></span>
<span class="line"><span>│   └── SKILL.md</span></span>
<span class="line"><span>└── architecture-overview/</span></span>
<span class="line"><span>    └── SKILL.md</span></span></code></pre></div><p>On startup, harness9 automatically scans all subdirectories under <code>{workdir}/skills/</code> and loads each one&#39;s <code>SKILL.md</code>.</p><h2 id="_3-skill-file-format" tabindex="-1">3. Skill File Format <a class="header-anchor" href="#_3-skill-file-format" aria-label="Permalink to &quot;3. Skill File Format&quot;">​</a></h2><p>Each <code>SKILL.md</code> is a standard Markdown file that starts with YAML frontmatter:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go-refactor</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Use when refactoring Go code — team conventions and patterns</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">trigger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refactor, clean up, restructure, simplify&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Go 重构指南</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 重构前必做</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`go vet ./...\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 确认无静态分析错误</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`go test ./...\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 确认测试全部通过</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 查看 git diff 确认修改范围</span></span></code></pre></div><h3 id="frontmatter-field-reference" tabindex="-1">frontmatter Field Reference <a class="header-anchor" href="#frontmatter-field-reference" aria-label="Permalink to &quot;frontmatter Field Reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td><strong>Yes</strong></td><td>Unique skill identifier (used by the <code>use_skill</code> tool call)</td></tr><tr><td><code>description</code></td><td>string</td><td><strong>Yes</strong></td><td>Short description injected into the System Prompt index, helping the LLM decide when to use it</td></tr><tr><td><code>trigger</code></td><td>string</td><td>No</td><td>Trigger keywords, documentation only, not used for automatic matching</td></tr></tbody></table><h2 id="_4-trigger-mechanisms" tabindex="-1">4. Trigger Mechanisms <a class="header-anchor" href="#_4-trigger-mechanisms" aria-label="Permalink to &quot;4. Trigger Mechanisms&quot;">​</a></h2><p>Skills support two trigger mechanisms:</p><h3 id="_4-1-tool-calling-primary-mechanism" tabindex="-1">4.1 Tool-Calling (Primary Mechanism) <a class="header-anchor" href="#_4-1-tool-calling-primary-mechanism" aria-label="Permalink to &quot;4.1 Tool-Calling (Primary Mechanism)&quot;">​</a></h3><p>After seeing the skills index in the System Prompt, the LLM autonomously decides whether a given skill is needed and triggers it by calling the <code>use_skill</code> tool:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>End of System Prompt (skills index) → LLM identifies an applicable skill</span></span>
<span class="line"><span>  → tool_use: {name: &quot;use_skill&quot;, arguments: {skill_name: &quot;go-refactor&quot;}}</span></span>
<span class="line"><span>  → the framework loads the SKILL.md body and returns it as a tool_result</span></span>
<span class="line"><span>  → the LLM continues execution under the full skill instructions</span></span></code></pre></div><h3 id="_4-2-slash-commands-cli-shortcut-path" tabindex="-1">4.2 Slash Commands (CLI Shortcut Path) <a class="header-anchor" href="#_4-2-slash-commands-cli-shortcut-path" aria-label="Permalink to &quot;4.2 Slash Commands (CLI Shortcut Path)&quot;">​</a></h3><p>In CLI REPL mode, users can directly type <code>/skill-name</code> to trigger a skill; the framework loads the body directly, bypassing the LLM&#39;s judgment:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/go-refactor               → prompt = skill body</span></span>
<span class="line"><span>/go-refactor 清理 main.go  → prompt = skill body + &quot;\\n\\n&quot; + &quot;清理 main.go&quot;</span></span></code></pre></div><blockquote><p>Slash commands are only supported in CLI mode (non-TTY pipe environments); in TUI mode, skills are activated via the <code>/skill</code> command or direct conversation.</p></blockquote><h2 id="_5-system-prompt-injection-result" tabindex="-1">5. System Prompt Injection Result <a class="header-anchor" href="#_5-system-prompt-injection-result" aria-label="Permalink to &quot;5. System Prompt Injection Result&quot;">​</a></h2><p>Once harness9 starts, the skills index is appended to the end of the System Prompt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Available Skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Use the \`use_skill\` tool to load the full content of any skill when needed.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- go-refactor: Use when refactoring Go code — team conventions and patterns</span></span>
<span class="line"><span>- testing-guide: Use when writing or reviewing tests</span></span>
<span class="line"><span>- deploy-guide: Use when deploying to production</span></span></code></pre></div><h2 id="_6-llm-calling-the-use-skill-tool" tabindex="-1">6. LLM Calling the use_skill Tool <a class="header-anchor" href="#_6-llm-calling-the-use-skill-tool" aria-label="Permalink to &quot;6. LLM Calling the use_skill Tool&quot;">​</a></h2><p>When the LLM determines that it needs the full content of a skill, it issues a tool call:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;use_skill&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;skill_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;go-refactor&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The tool returns the full body content of that skill file (everything after the frontmatter), and the LLM then uses this content to guide task execution.</p><h2 id="_7-module-implementation" tabindex="-1">7. Module Implementation <a class="header-anchor" href="#_7-module-implementation" aria-label="Permalink to &quot;7. Module Implementation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>skills.Skill</code></td><td><code>internal/skills/skill.go</code></td><td>Data structure + frontmatter parsing</td></tr><tr><td><code>skills.Index</code></td><td><code>internal/skills/index.go</code></td><td>Index summary + lazy full-text loading</td></tr><tr><td><code>skills.LoadSkills</code></td><td><code>internal/skills/loader.go</code></td><td>Scans subdirectories to build the Index</td></tr><tr><td><code>skills.UseSkillTool</code></td><td><code>internal/skills/use_skill_tool.go</code></td><td><code>use_skill</code> tool implementation</td></tr><tr><td><code>context.DefaultPromptBuilder</code></td><td><code>internal/context/builder.go</code></td><td>Assembles the System Prompt</td></tr></tbody></table><h2 id="_8-error-handling" tabindex="-1">8. Error Handling <a class="header-anchor" href="#_8-error-handling" aria-label="Permalink to &quot;8. Error Handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Behavior</th></tr></thead><tbody><tr><td><code>skills/</code> directory does not exist</td><td>Returns an empty Index, silently skipped</td></tr><tr><td>Subdirectory missing <code>SKILL.md</code></td><td>Skips the directory, prints a warn log</td></tr><tr><td>Skill file missing <code>name</code> or <code>description</code></td><td>Skips the file, prints a warn log</td></tr><tr><td><code>use_skill</code> called with a nonexistent skill</td><td>Returns an error message containing the list of available names, allowing the LLM to self-heal</td></tr><tr><td>CLI slash command points to a nonexistent skill</td><td>Prints the error to stderr, continues the REPL loop</td></tr><tr><td><code>AGENTS.md</code> does not exist</td><td>PromptBuilder skips this section</td></tr></tbody></table><h2 id="_9-cli-startup" tabindex="-1">9. CLI Startup <a class="header-anchor" href="#_9-cli-startup" aria-label="Permalink to &quot;9. CLI Startup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness9</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # TTY → TUI, pipe/CI → CLI REPL</span></span></code></pre></div>`,36)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
